// {{{ Data collection
// Everything here comes out of Prometheus. The restic units themselves export
// nothing, so "did the backup run" is answered by the timer's last trigger
// rather than by asking restic -- n8n is DynamicUser-sandboxed and cannot
// shell out to `restic snapshots` even if it wanted to.
const PROM = 'http://127.0.0.1:8451/api/v1/query';

const query = async (expr) => {
  const res = await this.helpers.httpRequest({ method: 'GET', url: PROM, qs: { query: expr }, json: true });
  return res?.data?.result ?? [];
};

const BACKUP_SETS = [
  { unit: 'restic-backups-data', label: 'data', detail: '/persist/data -> raid5pool' },
  { unit: 'restic-backups-state', label: 'state', detail: '/persist/state -> raid5pool' },
  { unit: 'restic-backups-offsite', label: 'offsite', detail: 'photos+docs+db -> backblaze b2' },
];

// All three timers are OnCalendar=daily, so anything past ~30h has skipped a
// run and anything past ~50h has skipped two.
const STALE_WARN_HOURS = 30;
const STALE_CRIT_HOURS = 50;
const POOL_WARN_PCT = 80;
const POOL_CRIT_PCT = 90;

const [triggers, failed, poolHealth, poolSize, poolFree, poolFrag, datasetUsed, poolGrowth] = await Promise.all([
  query('node_systemd_timer_last_trigger_seconds{name=~"restic-backups-.*"}'),
  query('node_systemd_unit_state{name=~"restic-backups-.*\\\\.service",state="failed"}'),
  query('zfs_pool_health'),
  query('zfs_pool_size_bytes'),
  query('zfs_pool_free_bytes'),
  query('zfs_pool_fragmentation_ratio'),
  query('zfs_dataset_used_bytes{type="filesystem"}'),
  // Negative values are fine and meaningful: a pool that shrank had something
  // pruned or destroyed, which is worth seeing rather than clamping away.
  query('zfs_pool_allocated_bytes - (zfs_pool_allocated_bytes offset 7d)'),
]);

const num = (s) => Number(s.value[1]);
const byLabel = (series, key) => Object.fromEntries(series.map((s) => [s.metric[key], num(s)]));

const lastTrigger = byLabel(triggers, 'name');
const failedUnits = new Set(failed.filter((s) => num(s) === 1).map((s) => s.metric.name));
const health = byLabel(poolHealth, 'pool');
const size = byLabel(poolSize, 'pool');
const free = byLabel(poolFree, 'pool');
const frag = byLabel(poolFrag, 'pool');
const used = byLabel(datasetUsed, 'name');
const growth = byLabel(poolGrowth, 'pool');
// }}}

// {{{ Evaluation
const now = Date.now() / 1000;
const gib = (b) => `${(b / 1024 ** 3).toFixed(1)} GiB`;
const tib = (b) => `${(b / 1024 ** 4).toFixed(2)} TiB`;
const human = (b) => (Math.abs(b) >= 1024 ** 4 ? tib(b) : gib(b));

const age = (hours) => {
  if (hours < 1) return `${Math.round(hours * 60)}m ago`;
  if (hours < 48) return `${hours.toFixed(1)}h ago`;
  return `${Math.floor(hours / 24)}d ago`;
};

const sets = BACKUP_SETS.map((set) => {
  const ts = lastTrigger[`${set.unit}.timer`];
  const isFailed = failedUnits.has(`${set.unit}.service`);

  if (isFailed) return { ...set, value: 'FAILED', extra: ts ? age((now - ts) / 3600) : '', level: 'critical' };
  // A timer with no last-trigger metric has never fired since boot. That is
  // not the same as a failure, but it is not evidence of a backup either.
  if (ts === undefined) return { ...set, value: 'NEVER RAN', extra: 'no trigger since boot', level: 'critical' };

  const hours = (now - ts) / 3600;
  const level = hours >= STALE_CRIT_HOURS ? 'critical' : hours >= STALE_WARN_HOURS ? 'warn' : 'ok';
  return { ...set, value: age(hours), extra: level === 'ok' ? '' : 'skipped a run', level };
});

const pools = Object.keys(health).sort().map((pool) => {
  const total = size[pool];
  const avail = free[pool];
  const pct = total ? 100 * (1 - avail / total) : 0;
  const weekly = growth[pool] ?? 0;
  // Only extrapolate when the pool is actually growing; a flat or shrinking
  // pool has no meaningful date at which it fills up.
  const weeksToFull = weekly > 0 ? ((total * (POOL_CRIT_PCT / 100)) - (total - avail)) / weekly : null;

  return {
    pool,
    healthy: health[pool] === 0,
    pct,
    used: total - avail,
    total,
    frag: frag[pool],
    weekly,
    weeksToFull,
    level: health[pool] !== 0 ? 'critical' : pct >= POOL_CRIT_PCT ? 'critical' : pct >= POOL_WARN_PCT ? 'warn' : 'ok',
  };
});

const REPO_DATASET = 'raid5pool/backups';
const repoSize = used[REPO_DATASET];

const rows = [
  ...sets.map((s) => ({ label: `last run · ${s.label}`, value: s.value, detail: s.extra || s.detail, level: s.level })),
  {
    label: 'local repo size',
    value: repoSize === undefined ? 'unknown' : human(repoSize),
    detail: REPO_DATASET,
    level: repoSize === undefined ? 'warn' : 'ok',
  },
];

const poolRows = pools.map((p) => ({
  label: `${p.pool}`,
  value: `${p.pct.toFixed(1)}%`,
  detail: `${human(p.used)} / ${human(p.total)}${p.frag === undefined ? '' : ` · ${p.frag.toFixed(0)}% frag`}`,
  level: p.level,
}));

const growthRows = pools.map((p) => {
  const trend = p.weekly === 0 ? 'flat' : `${p.weekly > 0 ? '+' : '-'}${human(Math.abs(p.weekly))}/wk`;
  const forecast =
    p.weeksToFull === null
      ? 'no growth'
      : p.weeksToFull <= 0
        ? `already past ${POOL_CRIT_PCT}%`
        : p.weeksToFull < 104
          ? `~${Math.round(p.weeksToFull)}wk to ${POOL_CRIT_PCT}%`
          : '>2yr headroom';

  return {
    label: p.pool,
    value: trend,
    detail: forecast,
    level: p.weeksToFull !== null && p.weeksToFull > 0 && p.weeksToFull < 8 ? 'warn' : 'ok',
  };
});

const all = [...rows, ...poolRows, ...growthRows];
const overall = all.some((r) => r.level === 'critical') ? 'critical' : all.some((r) => r.level === 'warn') ? 'warn' : 'ok';
// }}}

// {{{ Terminal-styled design tokens (shared with the health-monitor digest)
const palette = {
  bg: '#eef1f5',
  card: '#0b0f14',
  cardBorder: '#1c2530',
  divider: '#182029',
  text: '#d6e0ea',
  muted: '#5b7284',
  comment: '#4a7a6b',
  ok: '#3ddc84',
  warn: '#ffb454',
  critical: '#ff5c7a',
};
const tag = { ok: '[ OK ]', warn: '[WARN]', critical: '[CRIT]' };
const overallCopy = {
  ok: 'BACKUPS CURRENT',
  warn: 'BACKUPS NEED A LOOK',
  critical: 'BACKUPS AT RISK',
}[overall];
const mono = "ui-monospace,'JetBrains Mono','SFMono-Regular',Menlo,Consolas,'Liberation Mono',monospace";
// }}}

// {{{ Render
// Each item renders as up to two rows: the label/value line, then the detail
// on its own full-width row. Putting the detail in the label cell instead made
// it wrap after three or four characters, because the nowrap label keeps that
// column shrink-to-fit.
const section = (items) =>
  items
    .map((r) => {
      const c = palette[r.level];
      const border = `border-bottom:1px solid ${palette.divider};`;
      const main = `<tr>
      <td style="padding:9px 28px ${r.detail ? '2px' : '9px'} 28px;${r.detail ? '' : border}font-family:${mono};font-size:13px;color:${palette.muted};white-space:nowrap;">${r.label}</td>
      <td style="padding:9px 4px ${r.detail ? '2px' : '9px'} 4px;${r.detail ? '' : border}font-family:${mono};font-size:13px;color:${palette.cardBorder};width:100%;">${'·'.repeat(14)}</td>
      <td style="padding:9px 28px ${r.detail ? '2px' : '9px'} 28px;${r.detail ? '' : border}font-family:${mono};font-size:13px;text-align:right;white-space:nowrap;">
        <span style="color:${palette.text};">${r.value}</span>
        <span style="color:${c};font-weight:700;margin-left:10px;">${tag[r.level]}</span>
      </td>
    </tr>`;

      if (!r.detail) return main;

      return `${main}
    <tr>
      <td colspan="3" style="padding:0 28px 9px 28px;${border}font-family:${mono};font-size:11px;color:${palette.muted};opacity:0.7;">${r.detail}</td>
    </tr>`;
    })
    .join('\n');

const timestamp = new Date().toLocaleString('en-GB', { timeZone: 'Europe/Berlin', dateStyle: 'medium', timeStyle: 'short' });
const oc = palette[overall];

const html = `<!DOCTYPE html>
<html>
  <body style="margin:0;padding:32px 16px;background:${palette.bg};font-family:${mono};">
    <table role="presentation" width="100%" style="max-width:600px;margin:0 auto;">
      <tr>
        <td style="background:${palette.card};border:1px solid ${palette.cardBorder};border-radius:6px;overflow:hidden;">
          <table role="presentation" width="100%" style="border-collapse:collapse;">
            <tr><td style="height:4px;line-height:4px;font-size:0;background:${oc};">&nbsp;</td></tr>
            <tr>
              <td style="padding:28px 28px 20px 28px;">
                <div style="font-family:${mono};font-size:12px;color:${palette.comment};">$ systemctl list-timers 'restic-*' &amp;&amp; zpool list</div>
                <div style="font-family:${mono};font-size:21px;font-weight:700;letter-spacing:0.04em;color:${palette.text};margin-top:14px;">BACKUP_AND_STORAGE</div>
                <div style="font-family:${mono};font-size:14px;font-weight:700;color:${oc};margin-top:8px;">${tag[overall]} ${overallCopy}</div>
                <div style="font-family:${mono};font-size:12px;color:${palette.muted};margin-top:10px;">${timestamp} · inari · weekly</div>
              </td>
            </tr>
            <tr><td style="border-top:1px solid ${palette.cardBorder};"></td></tr>
            <tr><td style="padding:16px 28px 2px 28px;font-family:${mono};font-size:12px;color:${palette.comment};"># backup sets</td></tr>
            <tr><td style="padding:0 0 8px 0;"><table role="presentation" width="100%" style="border-collapse:collapse;">${section(rows)}</table></td></tr>
            <tr><td style="padding:18px 28px 2px 28px;font-family:${mono};font-size:12px;color:${palette.comment};"># pool capacity</td></tr>
            <tr><td style="padding:0 0 8px 0;"><table role="presentation" width="100%" style="border-collapse:collapse;">${section(poolRows)}</table></td></tr>
            <tr><td style="padding:18px 28px 2px 28px;font-family:${mono};font-size:12px;color:${palette.comment};"># growth (7d) and forecast</td></tr>
            <tr><td style="padding:0 0 20px 0;"><table role="presentation" width="100%" style="border-collapse:collapse;">${section(growthRows)}</table></td></tr>
            <tr><td style="border-top:1px solid ${palette.cardBorder};"></td></tr>
            <tr>
              <td style="padding:16px 28px;font-family:${mono};font-size:11px;color:${palette.muted};">
                anything under /raid5pool is outside impermanence and the local restic sets &mdash; only the explicit yomi.restic.offsite.paths are copied off-site.
              </td>
            </tr>
          </table>
        </td>
      </tr>
    </table>
  </body>
</html>`;
// }}}

return [{ json: { subject: `[inari] ${tag[overall]} backup & storage · ${overallCopy}`, html } }];
